import csv
from collections import defaultdict
from pathlib import Path
import hashlib

def read(name):
    with Path('lab', name + '.csv').open(newline='') as stream:
        return list(csv.DictReader(stream))

def key(row):
    return tuple(row[field] for field in ('run','report','employee'))

events = defaultdict(dict)
mail = defaultdict(list)
for row in read('events'):
    assert row['event'] not in events[key(row)]
    events[key(row)][row['event']] = int(row['ts_ms'])
for row in read('mail'):
    mail[key(row)].append(row['reason'])
assert set(mail) <= set(events)
for capture in read('captures'):
    run = capture['run']
    rows = sorted((k, v) for k, v in events.items() if k[0] == run)
    assert len({k[1] for k, _ in rows}) == 3
    assert capture['server_export'] == capture['mail_export'] == 'complete'
    end = int(capture['end_ms'])
    ready_times = [v['ready'] for k, v in rows]
    span = max(ready_times) - min(ready_times)
    assert end >= max(ready_times) + 1500
    print(run, capture['profile'], 'span', span, 'window through', end)
    for k, v in rows:
        assert v['ready'] <= v['edge_ack'] <= v['badge'] <= end
        print(*k[1:], v['ready'], v['edge_ack'], v['badge'], v['badge']-v['ready'], mail[k].count('report_ready'), *mail[k])
    assert (span, [v['badge']-v['ready'] for _, v in rows]) == {
        'D93': (10, [510, 785, 1910]),
        'S94': (7000, [600, 600, 600]),
    }[run]
    assert all('report_ready' not in mail[k] for k, _ in rows)

paths = sorted([path for folder in ('draft', 'lab') for path in Path(folder).rglob('*') if path.is_file()])
for path in paths:
    print(hashlib.sha256(path.read_bytes()).hexdigest(), path)
